namespace sv_43bbcea8326b4f4b8b4899c9d27aa23b.Services;

public sealed record Recipe(int Id, string Title, string Description, int PrepTimeMinutes);

public interface IRecipeService
{
    Task<List<Recipe>> GetByCuisineAsync(int cuisineId, CancellationToken cancellationToken);
}

public sealed class RecipeService : IRecipeService
{
    private static readonly Dictionary<int, List<Recipe>> Data = new()
    {
        [1] = [
            new(1, "Margherita Pizza", "Classic pizza with fresh mozzarella, basil, and tomato sauce on a thin crust.", 30),
            new(2, "Spaghetti Carbonara", "Creamy pasta with eggs, pecorino cheese, guanciale, and black pepper.", 25),
            new(3, "Tiramisu", "Layered dessert with espresso-soaked ladyfingers and mascarpone cream.", 45),
            new(4, "Risotto alla Milanese", "Creamy saffron-infused risotto finished with butter and parmesan.", 40),
        ],
        [2] = [
            new(5, "Kung Pao Chicken", "Spicy stir-fried chicken with peanuts, chili peppers, and Sichuan peppercorns.", 35),
            new(6, "Mapo Tofu", "Silken tofu in a fiery sauce of doubanjiang, ground pork, and Sichuan pepper.", 20),
            new(7, "Xiaolongbao", "Delicate steamed soup dumplings filled with pork and a rich broth.", 90),
        ],
        [3] = [
            new(8, "Tacos al Pastor", "Spit-roasted pork tacos with pineapple, cilantro, and onion on corn tortillas.", 50),
            new(9, "Guacamole", "Fresh avocado dip with lime juice, cilantro, jalapeño, and tomato.", 10),
            new(10, "Churros", "Fried dough sticks coated in cinnamon sugar and served with chocolate sauce.", 35),
        ],
    };

    public async Task<List<Recipe>> GetByCuisineAsync(int cuisineId, CancellationToken cancellationToken)
    {
        // Simulate a slow backend API call.
        await Task.Delay(2000, cancellationToken);

        return Data.TryGetValue(cuisineId, out var recipes) ? recipes : [];
    }
}

@page "/recipes/{CuisineId:int}"
@rendermode InteractiveServer
@implements IDisposable
@inject IRecipeService RecipeService
@inject ILogger<Recipes> Logger
@inject NavigationManager Nav

@using sv_43bbcea8326b4f4b8b4899c9d27aa23b.Services
@using Microsoft.AspNetCore.Components.Routing

<PageTitle>Recipes</PageTitle>

<h1>Recipes</h1>

<nav class="mb-3">
    <a href="/recipes/1" class="btn btn-outline-primary me-1 @(CuisineId == 1 ? "active" : "")">Italian</a>
    <a href="/recipes/2" class="btn btn-outline-primary me-1 @(CuisineId == 2 ? "active" : "")">Chinese</a>
    <a href="/recipes/3" class="btn btn-outline-primary me-1 @(CuisineId == 3 ? "active" : "")">Mexican</a>
</nav>

@if (_errorMessage is not null)
{
    <div class="alert alert-danger d-flex align-items-center justify-content-between" role="alert">
        <span>@_errorMessage</span>
        <button class="btn btn-outline-danger btn-sm ms-3" @onclick="RetryAsync">Retry</button>
    </div>
}
else if (_recipes is null)
{
    <div class="d-flex align-items-center gap-2 my-4">
        <div class="spinner-border text-primary" role="status"></div>
        <span>Loading recipes…</span>
    </div>
}
else
{
    @if (_isRefreshing)
    {
        <div class="alert alert-info py-1 px-3 d-inline-flex align-items-center gap-2 mb-3" role="status">
            <div class="spinner-border spinner-border-sm"></div>
            <span>Refreshing…</span>
        </div>
    }

    <div class="row row-cols-1 row-cols-md-2 g-3">
        @foreach (var recipe in DisplayedRecipes)
        {
            <div class="col">
                <div class="card h-100">
                    <div class="card-body">
                        <h5 class="card-title">@recipe.Title</h5>
                        <p class="card-text">@recipe.Description</p>
                    </div>
                    <div class="card-footer text-body-secondary">
                        Prep time: @recipe.PrepTimeMinutes min
                    </div>
                </div>
            </div>
        }
    </div>

    @if (!DisplayedRecipes.Any())
    {
        <p class="text-muted">No recipes found for this cuisine.</p>
    }
}

@code {
    [Parameter] public int CuisineId { get; set; }
    [SupplyParameterFromQuery(Name = "sort")] public string? Sort { get; set; }

    private List<Recipe>? _recipes;
    private bool _isRefreshing;
    private string? _errorMessage;
    private int _loadedCuisineId;

    private CancellationTokenSource? _loadCts;
    private readonly CancellationTokenSource _disposeCts = new();

    private IEnumerable<Recipe> DisplayedRecipes =>
        string.Equals(Sort, "newest", StringComparison.OrdinalIgnoreCase)
            ? _recipes!.OrderByDescending(r => r.Id)
            : string.Equals(Sort, "popular", StringComparison.OrdinalIgnoreCase)
                ? _recipes!.OrderBy(r => r.PrepTimeMinutes)
                : _recipes!;

    protected override Task OnParametersSetAsync()
    {
        // Only reload data when the cuisine changes — sort changes are display-only.
        if (CuisineId == _loadedCuisineId && _recipes is not null)
            return Task.CompletedTask;

        return LoadRecipesAsync();
    }

    private async Task LoadRecipesAsync()
    {
        // Cancel any in-flight load for the previous cuisine.
        await CancelPendingLoadAsync();

        _errorMessage = null;
        _isRefreshing = _recipes is not null;
        _loadedCuisineId = CuisineId;

        var cts = CancellationTokenSource.CreateLinkedTokenSource(_disposeCts.Token);
        _loadCts = cts;

        try
        {
            var result = await RecipeService.GetByCuisineAsync(CuisineId, cts.Token);

            // Guard against a stale callback after cancellation.
            if (cts.Token.IsCancellationRequested)
                return;

            _recipes = result;
        }
        catch (OperationCanceledException) when (cts.Token.IsCancellationRequested)
        {
            // Expected when the user switched cuisines or navigated away.
        }
        catch (TimeoutException ex)
        {
            Logger.LogError(ex, "Timeout loading recipes for cuisine {CuisineId}", CuisineId);
            _errorMessage = "The request timed out. Please try again.";
        }
        catch (Exception ex)
        {
            Logger.LogError(ex, "Error loading recipes for cuisine {CuisineId}", CuisineId);
            _errorMessage = "Something went wrong while loading recipes. Please try again.";
        }
        finally
        {
            _isRefreshing = false;
        }
    }

    private async Task RetryAsync() => await LoadRecipesAsync();

    private async Task CancelPendingLoadAsync()
    {
        if (_loadCts is not null)
        {
            await _loadCts.CancelAsync();
            _loadCts.Dispose();
            _loadCts = null;
        }
    }

    public void Dispose()
    {
        _disposeCts.Cancel();
        _disposeCts.Dispose();
        _loadCts?.Dispose();
    }
}

